class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        N = n + m - 1

        # ans[j] will hold the character for position j, '' means not assigned yet
        ans = [''] * N

        # Process forced positions from 'T' intervals
        for i in range(n):
            if str1[i] == 'T':
                for k in range(m):
                    j = i + k
                    c = str2[k]
                    if ans[j] == '':
                        ans[j] = c
                    elif ans[j] != c:
                        return ""

        # For each 'F' interval compute how many positions are already forced to match
        forced_match = [0] * n   # number of forced matches for each interval
        satisfied = [False] * n  # whether the interval already has a mismatch

        for i in range(n):
            if str1[i] == 'F':
                match_cnt = 0
                sat = False
                for j in range(i, i + m):
                    if ans[j] != '':
                        if ans[j] != str2[j - i]:
                            sat = True
                            break
                        else:
                            match_cnt += 1
                if sat:
                    satisfied[i] = True
                else:
                    forced_match[i] = match_cnt
                    if match_cnt == m:          # all positions forced to match -> impossible
                        return ""

        # Greedy construction from left to right
        for j in range(N):
            # indices of intervals that cover position j
            i_start = j - m + 1
            if i_start < 0:
                i_start = 0
            i_end = j
            if i_end >= n:
                i_end = n - 1

            is_forced = (ans[j] != '')
            char = None

            if not is_forced:
                # Determine which letters are forbidden at this position
                forbidden = [False] * 26
                for i in range(i_start, i_end + 1):
                    if str1[i] == 'F' and not satisfied[i]:
                        offset = j - i
                        ch = str2[offset]
                        idx = ord(ch) - 97
                        # if this is the last free position of the interval, the matching char would make it impossible
                        if forced_match[i] + 1 == m:
                            forbidden[idx] = True
                # pick the smallest allowed character
                for c in range(26):
                    if not forbidden[c]:
                        char = chr(c + 97)
                        break
                if char is None:
                    return ""
                ans[j] = char
            else:
                char = ans[j]
                # forced position: it is already fixed, no need to check forbidden

            # Update intervals according to the chosen character
            for i in range(i_start, i_end + 1):
                if str1[i] == 'F' and not satisfied[i]:
                    offset = j - i
                    if char == str2[offset]:
                        # we add a new forced match only if the position was previously free
                        if not is_forced:
                            forced_match[i] += 1
                            if forced_match[i] == m:
                                return ""
                    else:
                        satisfied[i] = True

        # Final check: all 'F' intervals must be satisfied
        for i in range(n):
            if str1[i] == 'F' and not satisfied[i]:
                return ""

        return ''.join(ans)

