INF = 10 ** 18


def solve() -> None:
    it = iter(map(int, sys.stdin.buffer.read().split()))
    N = next(it)
    W = [next(it) for _ in range(N)]
    L = [0] * N
    R = [0] * N
    for i in range(N):
        L[i] = next(it)
        R[i] = next(it)

    max_pos = 2 * N                      # coordinates are in [1 .. 2N]

    # minima for each exact coordinate
    min_at_L = [INF] * (max_pos + 1)
    min_at_R = [INF] * (max_pos + 1)
    for i in range(N):
        l, r, w = L[i], R[i], W[i]
        if w < min_at_L[l]:
            min_at_L[l] = w
        if w < min_at_R[r]:
            min_at_R[r] = w

    # ---------- segment tree (iterative) ----------
    size = 1
    while size < max_pos + 1:
        size <<= 1

    segL = [INF] * (2 * size)
    segR = [INF] * (2 * size)

    for i in range(1, max_pos + 1):
        segL[size + i] = min_at_L[i]
        segR[size + i] = min_at_R[i]

    for i in range(size - 1, 0, -1):
        segL[i] = segL[i << 1] if segL[i << 1] < segL[i << 1 | 1] else segL[i << 1 | 1]
        segR[i] = segR[i << 1] if segR[i << 1] < segR[i << 1 | 1] else segR[i << 1 | 1]

    def range_min(seg, l, r):
        """minimum on inclusive interval [l, r] (1‑based)"""
        if l > r:
            return INF
        l += size - 1
        r += size - 1
        res = INF
        while l <= r:
            if l & 1:
                if seg[l] < res:
                    res = seg[l]
                l += 1
            if not (r & 1):
                if seg[r] < res:
                    res = seg[r]
                r -= 1
            l >>= 1
            r >>= 1
        return res

    Q = next(it)
    out_lines = []
    for _ in range(Q):
        s = next(it) - 1
        t = next(it) - 1

        Ls, Rs, Ws = L[s], R[s], W[s]
        Lt, Rt, Wt = L[t], R[t], W[t]

        # disjoint -> direct edge
        if Rs < Lt or Rt < Ls:
            out_lines.append(str(Ws + Wt))
            continue

        # overlapping case
        # make Ls <= Lt to simplify the two‑intermediate formula
        if Ls > Lt:
            Ls, Rs, Ws, Lt, Rt, Wt = Lt, Rt, Wt, Ls, Rs, Ws

        # common neighbour (left of both or right of both)
        left_bound = Ls                # = min(Ls, Lt)
        right_bound = Rs if Rs > Rt else Rt   # = max(Rs, Rt)

        best = INF
        if left_bound > 1:
            v = range_min(segR, 1, left_bound - 1)
            if v < best:
                best = v
        if right_bound < max_pos:
            v = range_min(segL, right_bound + 1, max_pos)
            if v < best:
                best = v

        # two intermediates: a right of s intersecting t, b left of t intersecting s
        if Rs + 1 <= Rt:
            wA = range_min(segL, Rs + 1, Rt)
            if wA < INF:
                if Ls <= Lt - 1:
                    wB = range_min(segR, Ls, Lt - 1)
                    if wB < INF:
                        total = wA + wB
                        if total < best:
                            best = total

        if best < INF:
            out_lines.append(str(Ws + Wt + best))
        else:
            out_lines.append("-1")

    sys.stdout.write("\n".join(out_lines))


