from typing import List

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        # Transform (x, y) -> (u, v) where Manhattan distance = max(|u1-u2|, |v1-v2|)
        u = [x + y for x, y in points]
        v = [x - y for x, y in points]

        # Sort points by (u, v) to help pruning
        idx = sorted(range(n), key=lambda i: (u[i], v[i]))
        u_sorted = [u[i] for i in idx]
        v_sorted = [v[i] for i in idx]

        # Check if we can choose k points with pairwise distance >= D
        def feasible(D: int) -> bool:
            if D <= 0:
                return n >= k
            selected = []  # indices of chosen points (in sorted order)

            def dfs(pos: int, depth: int) -> bool:
                if depth == k:
                    return True
                # Not enough points left to reach k
                if n - pos < k - depth:
                    return False
                for i in range(pos, n):
                    ui = u_sorted[i]
                    vi = v_sorted[i]
                    # Verify compatibility with already selected points
                    ok = True
                    for sel in selected:
                        if abs(u_sorted[sel] - ui) < D and abs(v_sorted[sel] - vi) < D:
                            ok = False
                            break
                    if ok:
                        selected.append(i)
                        if dfs(i + 1, depth + 1):
                            return True
                        selected.pop()
                return False

            return dfs(0, 0)

        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

