import heapq

def solve() -> None:
    data = sys.stdin.read().splitlines()
    N = int(data[0].strip())
    rows = data[1:]

    # out[v][c] = list of destinations w with edge v -c-> w
    # in [v][c] = list of sources    u with edge u -c-> v
    out = [dict() for _ in range(N)]
    inn = [dict() for _ in range(N)]

    for i in range(N):
        line = rows[i].strip()
        for j, ch in enumerate(line):
            if ch == '-':
                continue
            c = ord(ch) - ord('a')
            # outgoing
            lst = out[i].get(c)
            if lst is None:
                out[i][c] = [j]
            else:
                lst.append(j)
            # incoming
            lst = inn[j].get(c)
            if lst is None:
                inn[j][c] = [i]
            else:
                lst.append(i)

    INF = 10 ** 9
    dist = [[INF] * N for _ in range(N)]
    heap = []

    # sources: (i,i) with distance 0
    for i in range(N):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))

    # sources: direct edges with distance 1
    for i in range(N):
        for c, dests in out[i].items():
            for j in dests:
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(heap, (1, i, j))

    # Dijkstra on the reversed product graph
    while heap:
        d, x, y = heapq.heappop(heap)
        if d != dist[x][y]:
            continue
        nd = d + 2
        in_dict = inn[x]
        out_dict = out[y]

        # iterate over the smaller dictionary
        if len(in_dict) <= len(out_dict):
            for c, src_list in in_dict.items():
                dest_list = out_dict.get(c)
                if dest_list is None:
                    continue
                for p in src_list:
                    row = dist[p]
                    for q in dest_list:
                        if nd < row[q]:
                            row[q] = nd
                            heapq.heappush(heap, (nd, p, q))
        else:
            for c, dest_list in out_dict.items():
                src_list = in_dict.get(c)
                if src_list is None:
                    continue
                for q in dest_list:
                    for p in src_list:
                        if nd < dist[p][q]:
                            dist[p][q] = nd
                            heapq.heappush(heap, (nd, p, q))

    # output
    out_lines = []
    for i in range(N):
        out_lines.append(' '.join(str(-1 if x == INF else x) for x in dist[i]))
    sys.stdout.write('\n'.join(out_lines))

