from typing import List

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        # find the two '*' positions
        stars = [i for i, ch in enumerate(p) if ch == '*']
        star1, star2 = stars[0], stars[1]
        prefix = p[:star1]
        middle = p[star1 + 1:star2]
        suffix = p[star2 + 1:]

        # KMP to find all occurrences of a pattern in s
        def kmp(text: str, pat: str) -> List[int]:
            if not pat:
                return []
            m = len(pat)
            # compute prefix function
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j
            # search
            res = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        res.append(i - m + 1)
                        j = pi[j - 1]
            return res

        # matches for non‑empty parts
        prefix_matches = kmp(s, prefix) if prefix else []
        suffix_matches = kmp(s, suffix) if suffix else []

        # middle matches: if middle is empty we consider all split positions
        if middle:
            middle_matches = kmp(s, middle)
        else:
            middle_matches = list(range(n + 1))  # positions 0..n

        INF = 10 ** 9
        ans = INF

        Lp = len(prefix)
        Lm = len(middle)
        Ls = len(suffix)

        # case: both prefix and suffix are non‑empty
        if prefix and suffix:
            for m in middle_matches:
                # need a prefix ending before m
                bound_prefix = m - Lp
                if bound_prefix < 0:
                    continue
                idx = bisect_right(prefix_matches, bound_prefix) - 1
                if idx < 0:
                    continue
                p_start = prefix_matches[idx]

                # need a suffix starting after m+Lm-1
                bound_suffix = m + Lm
                jdx = bisect_left(suffix_matches, bound_suffix)
                if jdx >= len(suffix_matches):
                    continue
                s_start = suffix_matches[jdx]
                length = s_start + Ls - p_start
                if length < ans:
                    ans = length

        # case: prefix empty, suffix non‑empty
        elif not prefix and suffix:
            for m in middle_matches:
                bound_suffix = m + Lm
                jdx = bisect_left(suffix_matches, bound_suffix)
                if jdx >= len(suffix_matches):
                    continue
                s_start = suffix_matches[jdx]
                length = s_start + Ls - m
                if length < ans:
                    ans = length

        # case: prefix non‑empty, suffix empty
        elif prefix and not suffix:
            for m in middle_matches:
                bound_prefix = m - Lp
                if bound_prefix < 0:
                    continue
                idx = bisect_right(prefix_matches, bound_prefix) - 1
                if idx < 0:
                    continue
                p_start = prefix_matches[idx]
                length = m + Lm - p_start
                if length < ans:
                    ans = length

        # case: both prefix and suffix empty
        else:
            # pattern is "*middle*"
            if not middle:
                return 0
            if middle_matches:
                return Lm
            else:
                return -1

        return ans if ans != INF else -1

