# ------------------------------------------------------------
# Segment tree that stores (min, max) on each node
# supports range add, first index with value >= x,
# last index with value <= x, and point query
# ------------------------------------------------------------
class SegTree:
    def __init__(self, n):
        self.n = n
        size = 1
        while size < n:
            size <<= 1
        self.size = size
        self.mn = [INF] * (2 * size)
        self.mx = [-INF] * (2 * size)
        self.lz = [0] * (2 * size)
        # build leaves
        for i in range(n):
            v = i + 1          # initial f(x) = x
            self.mn[size + i] = v
            self.mx[size + i] = v
        # internal nodes
        for i in range(size - 1, 0, -1):
            self._pull(i)

    # pull children's information up
    def _pull(self, idx):
        self.mn[idx] = min(self.mn[idx << 1], self.mn[idx << 1 | 1])
        self.mx[idx] = max(self.mx[idx << 1], self.mx[idx << 1 | 1])

    # push lazy value to children
    def _push(self, idx):
        if self.lz[idx] != 0:
            val = self.lz[idx]
            for child in (idx << 1, idx << 1 | 1):
                self.mn[child] += val
                self.mx[child] += val
                self.lz[child] += val
            self.lz[idx] = 0

    # range add
    def add(self, l, r, val, idx=1, left=1, right=None):
        if right is None:
            right = self.size
        if r < left or right < l:
            return
        if l <= left and right <= r:
            self.mn[idx] += val
            self.mx[idx] += val
            self.lz[idx] += val
            return
        self._push(idx)
        mid = (left + right) >> 1
        self.add(l, r, val, idx << 1, left, mid)
        self.add(l, r, val, idx << 1 | 1, mid + 1, right)
        self._pull(idx)

    # first index with value >= target, None if not exist
    def first_ge(self, target, idx=1, left=1, right=None):
        if right is None:
            right = self.size
        if self.mx[idx] < target:
            return None
        if left == right:
            return left
        self._push(idx)
        mid = (left + right) >> 1
        res = self.first_ge(target, idx << 1, left, mid)
        if res is not None:
            return res
        return self.first_ge(target, idx << 1 | 1, mid + 1, right)

    # last index with value <= target, None if not exist
    def last_le(self, target, idx=1, left=1, right=None):
        if right is None:
            right = self.size
        if self.mn[idx] > target:
            return None
        if left == right:
            return left
        self._push(idx)
        mid = (left + right) >> 1
        res = self.last_le(target, idx << 1 | 1, mid + 1, right)
        if res is not None:
            return res
        return self.last_le(target, idx << 1, left, mid)

    # point query (value at position pos)
    def point_query(self, pos, idx=1, left=1, right=None):
        if right is None:
            right = self.size
        if left == right:
            return self.mn[idx]
        self._push(idx)
        mid = (left + right) >> 1
        if pos <= mid:
            return self.point_query(pos, idx << 1, left, mid)
        else:
            return self.point_query(pos, idx << 1 | 1, mid + 1, right)

    # collect all values of the first n positions into a list
    def collect(self, n):
        ans = [0] * n
        self._collect(1, 1, self.size, ans, n)
        return ans

    def _collect(self, idx, left, right, ans, n):
        if left == right:
            if left <= n:
                ans[left - 1] = self.mn[idx]
            return
        self._push(idx)
        mid = (left + right) >> 1
        self._collect(idx << 1, left, mid, ans, n)
        self._collect(idx << 1 | 1, mid + 1, right, ans, n)


