import sys

def mat_mul(A, B, mod):
    """multiply two N x N matrices modulo mod"""
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ci = C[i]
        for k in range(n):
            aik = Ai[k]
            if aik == 0:
                continue
            Bk = B[k]
            for j in range(n):
                Ci[j] = (Ci[j] + aik * Bk[j]) % mod
    return C


def mat_pow(M, power, mod):
    """binary exponentiation of a square matrix"""
    n = len(M)
    # identity
    R = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    base = M
    e = power
    while e:
        if e & 1:
            R = mat_mul(R, base, mod)
        base = mat_mul(base, base, mod)
        e >>= 1
    return R


