    for i in range(N):
        for j in range(N):
            if A[i][j] != 0:
                C[i][j] = A[i][j] % p

    # C^p
    Cp = mat_pow(C, p, p)

    # extra contributions
    extra = [[0] * N for _ in range(N)]

    # zero self‑loops (any p >= 3)
    for i in range(N):
        if A[i][i] == 0:                     # zero self‑loop at i
            for j in range(N):
                if i == j:
                    continue
                if C[i][j] != 0:
                    extra[i][j] = (extra[i][j] + C[i][j]) % p
                if C[j][i] != 0:
                    extra[j][i] = (extra[j][i] + C[j][i]) % p

    # additional pattern for p = 3
    if p == 3:
        for i in range(N):
            for j in range(N):
                if A[i][j] == 0 and A[j][i] != 0:
                    extra[i][j] = (extra[i][j] + A[j][i]) % p

    # combine
    res = [[(Cp[i][j] + extra[i][j]) % p for j in range(N)] for i in range(N)]

    # multiply by (-1)^K
    if K & 1:          # K is odd
        for i in range(N):
            for j in range(N):
                res[i][j] = (p - res[i][j]) % p

    # output
    out = '\n'.join(' '.join(str(x) for x in row) for row in res)
    sys.stdout.write(out)


