class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7
        r = n - k                     # number of runs (maximal blocks of equal values)
        if r < 1 or r > n:            # invalid case (should not happen with given constraints)
            return 0

        # pre‑compute factorials and inverse factorials up to n
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * (n + 1)
        inv_fact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def comb(N: int, K: int) -> int:
            if K < 0 or K > N:
                return 0
            return fact[N] * inv_fact[K] % MOD * inv_fact[N - K] % MOD

        # ways to split n positions into r non‑empty runs (compositions)
        ways_lengths = comb(n - 1, r - 1)

        # ways to assign values to the r runs (adjacent runs must differ)
        ways_values = m * pow(m - 1, r - 1, MOD) % MOD

        return ways_lengths * ways_values % MOD

