def odd_part_sum(arr):
    """
    arr : list of odd positive integers
    returns Σ_{i ≤ j} f(arr[i] + arr[j])
    """
    n = len(arr)
    if n == 0:
        return 0
    if n == 1:
        # only pair (i,i) : f(odd+odd) = odd
        return arr[0]

    # maximal possible v2 of any sum
    max_val = arr[0]
    for v in arr:
        if v > max_val:
            max_val = v
    max_sum = max_val * 2
    max_k = max_sum.bit_length() - 1          # floor(log2(max_sum))

    total = 0
    # iterate over all possible k = v2(oi+oj)
    for k in range(1, max_k + 1):
        M = 1 << (k + 1)        # 2^{k+1}
        half = M >> 1           # 2^{k}

        # count and sum per residue modulo M
        d = {}
        for a in arr:
            r = a % M
            if r in d:
                cnt, s = d[r]
                d[r] = (cnt + 1, s + a)
            else:
                d[r] = (1, a)

        if k == 1:
            # only pairs with equal residue have v2 = 1
            # contribution of a class (c, S) :  S * (c + 1) / 2
            s = 0
            for cnt, ss in d.values():
                s += ss * (cnt + 1)
            total += s >> 1
        else:
            # pairs of different complementary residues
            for r, (cnt_r, sum_r) in d.items():
                s = (half - r) % M
                if s not in d:
                    continue
                if r < s:                     # count each unordered pair once
                    cnt_s, sum_s = d[s]
                    pair_sum = sum_r * cnt_s + sum_s * cnt_r
                    total += pair_sum >> k   # divide by 2^k
    return total

