    it = iter(data)
    N = int(next(it))
    A = [int(next(it)) for _ in range(N)]

    MAX_E = 24                     # because 2^24 > 1e7
    cnt = [0] * MAX_E
    sum_odd = [0] * MAX_E
    odds = [[] for _ in range(MAX_E)]

    for a in A:
        # trailing zero count  (v2)
        e = (a & -a).bit_length() - 1
        o = a >> e
        cnt[e] += 1
        sum_odd[e] += o
        odds[e].append(o)

    ans = 0

    # pairs of different exponents
    for e in range(MAX_E):
        if cnt[e] == 0:
            continue
        for e2 in range(e + 1, MAX_E):
            if cnt[e2] == 0:
                continue
            shift = 1 << (e2 - e)
            ans += cnt[e2] * sum_odd[e] + shift * cnt[e] * sum_odd[e2]

    # pairs inside each exponent group
    for e in range(MAX_E):
        if cnt[e] > 0:
            ans += odd_part_sum(odds[e])

    sys.stdout.write(str(ans))

