from typing import List

class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n
        self.components = n

    def find(self, x: int) -> int:
        # iterative path compression
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        # union by size
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self.components -= 1
        return True

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        dsu = DSU(n)

        # Map each value <= threshold to its index in nums
        max_val = threshold
        value_to_index = [-1] * (max_val + 1)
        small_vals = []                     # values that are <= threshold
        for i, v in enumerate(nums):
            if v <= threshold:
                value_to_index[v] = i
                small_vals.append(v)

        # For each multiple m (1..threshold) keep the first index that divides it
        first_idx = [-1] * (max_val + 1)

        # Connect numbers that share a common multiple m <= threshold
        for v in small_vals:
            idx = value_to_index[v]
            for m in range(v, max_val + 1, v):
                if first_idx[m] == -1:
                    first_idx[m] = idx
                else:
                    dsu.union(idx, first_idx[m])

        # DSU already counts isolated nodes (values > threshold) as separate components
        return dsu.components
